{
  "items": [
    {
      "name": "Real.neg_sqrt_lt_of_sq_lt",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, x ^ 2 < y → -√y < x"
    },
    {
      "name": "Real.sqrt_one_add_le",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, -1 ≤ x → √(1 + x) ≤ 1 + x / 2"
    },
    {
      "name": "Real.le_sqrt_of_sq_le",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, x ^ 2 ≤ y → x ≤ √y"
    },
    {
      "name": "Real.sq_sqrt'",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, √x ^ 2 = max x 0"
    },
    {
      "name": "Real.sqrt_le_iff",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, √x ≤ y ↔ 0 ≤ y ∧ x ≤ y ^ 2"
    },
    {
      "name": "Real.sqrt_lt",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, 0 ≤ x → 0 ≤ y → (√x < y ↔ x < y ^ 2)"
    }
  ]
}
